import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"EmakiAccessory","description":"","frontmatter":{},"headers":[],"relativePath":"modules/accessory/index.md","filePath":"modules/accessory/index.md","lastUpdated":0}`),a={name:`modules/accessory/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="emakiaccessory" tabindex="-1">EmakiAccessory <a class="header-anchor" href="#emakiaccessory" aria-label="Permalink to “EmakiAccessory”">​</a></h1><p>EmakiAccessory 是做什么的, 依赖哪些模块, 装好后会用到哪些文件, 以及你第一次怎么把它跑起来</p><p>EmakiAccessory 是 Emaki 系列的饰品栏模块. 你装上它, 玩家就多出一套自己的饰品栏 -- 这是一个独立的 GUI (图形界面) 窗口, 不占用原版装备槽位, 戴在里面的饰品照常提供属性与技能</p><p>饰品栏可以有多个页面: <code>parts.yml</code> 定义全局部位与槽位实例, <code>pages/*.yml</code> 决定每一页启用哪些部位, <code>gui/accessory_gui.yml</code> 描述页面布局. 每页数据各存一份, 互不覆盖, 但<strong>只有当前启用页</strong>的饰品才会产生属性, 技能与套装件数 (同一套装已戴的件数). 你不用在 EmakiAttribute 和 EmakiSkills 里另配槽位, 饰品的属性与技能会自动接入这两个模块</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to “基本信息”">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>模块版本</td><td><code>2.0.0</code></td></tr><tr><td>API 坐标</td><td><code>emaki.jiuwu.craft:emaki-accessory-api:2.0.0</code></td></tr><tr><td>主类</td><td><code>emaki.jiuwu.craft.accessory.EmakiAccessoryPlugin</code></td></tr><tr><td>主命令</td><td><code>/emakiaccessory</code></td></tr><tr><td>别名</td><td><code>/eaccessory</code>, <code>/eacc</code></td></tr><tr><td>硬依赖</td><td>EmakiCoreLib</td></tr><tr><td>软依赖</td><td>EmakiItem, EmakiAttribute, EmakiSkills, PlaceholderAPI</td></tr><tr><td>描述符基线</td><td><code>api-version: &quot;26.1&quot;</code>, <code>folia-supported: true</code></td></tr><tr><td>Java</td><td>Java 25</td></tr><tr><td>主要权限</td><td><code>emakiaccessory.use</code> (默认 true), <code>emakiaccessory.reload</code> (op), <code>emakiaccessory.debug</code> (op), <code>emakiaccessory.admin</code> (op), <code>emakiaccessory.admin.edit</code> (op), <code>emakiaccessory.page.secondary</code> (op, 页权限示例)</td></tr></tbody></table><h2 id="功能页面" tabindex="-1">功能页面 <a class="header-anchor" href="#功能页面" aria-label="Permalink to “功能页面”">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td><a href="./commands.html">命令与权限</a></td><td><code>/emakiaccessory</code> 的子命令, 页面取回, 管理指令与 6 个权限节点</td></tr><tr><td><a href="./configuration.html">配置详解</a></td><td><code>config.yml</code> 的槽位来源, 耐久度开关, 掉落, 去重与持久化, 以及 <code>pages/*.yml</code> 的字段</td></tr><tr><td><a href="./parts.html">部位与槽位</a></td><td><code>parts.yml</code> 的部位定义, 槽位实例展开规则与孤儿槽</td></tr><tr><td><a href="./sets.html">饰品套装</a></td><td><code>sets/&lt;套装&gt;.yml</code> 的成员, 槽位规则, 件数阈值与效果</td></tr><tr><td><a href="./gui.html">界面模板</a></td><td><code>gui/accessory_gui.yml</code> 的四种槽位类型与页面切换格</td></tr><tr><td><a href="./integration.html">属性与技能接入</a></td><td>饰品属性如何进入 EmakiAttribute, 技能如何进入 EmakiSkills</td></tr><tr><td><a href="./api.html">API 与集成</a></td><td><code>emaki-accessory-api</code> 的门面, 查询接口与线程约束</td></tr><tr><td><a href="./events.html">事件 API</a></td><td><code>AccessorySetBonusChangeEvent</code></td></tr></tbody></table><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to “核心能力”">​</a></h2><ul><li><strong>独立饰品栏</strong>: 饰品栏是自己的 GUI, 不占用原版装备槽位, 也不与 EmakiItem 的装备栏共享槽位</li><li><strong>多页与页间隔离</strong>: <code>pages/*.yml</code> 定义多页, 同一个槽位实例 id 在不同页各存一件饰品, 互不覆盖</li><li><strong>只有启用页生效</strong>: 非启用页的饰品保留数据但停止提供属性, 技能与套装件数; <code>page_enable</code> 格用于切换生效页</li><li><strong>按权限开放页</strong>: 页的 <code>permission</code> 非空时逐字判定; 失去权限不清数据, 不自动换页, 玩家用 <code>/eacc retrieve &lt;页&gt;</code> 取回</li><li><strong>部位展开为槽位实例</strong>: <code>parts.yml</code> 里一个部位配 <code>count: 2</code> 会展开出 <code>ring_1</code> 与 <code>ring_2</code> 两个槽位实例, 界面上一个格子对应一个实例</li><li><strong>属性与装备同源解析</strong>: 饰品属性走 EmakiAttribute 的同一个解析器, 一件饰品和一顶同数据的头盔产出完全相同的数值, 父属性展开与范围伴生键 (带范围属性的配套键) 一并生效</li><li><strong>累加式套装阈值</strong>: 套装档位是累加的. 戴够 3 件时, 2 件档与 3 件档<strong>同时</strong>生效, 不是互斥择一</li><li><strong>饰品套装与装备套装互不干扰</strong>: 饰品套装只统计饰品槽内的件数, EmakiItem 只统计装备栏. 同一件物品同时属于两边的套装是允许的, 两边各自独立计数</li><li><strong>孤儿槽不丢数据</strong>: 你缩减 <code>count</code>, 删除部位或把部位从某页移除, 都不会删数据. 该页不再声明的槽位里的饰品会变成&quot;孤儿&quot;, 显示在该页孤儿区供玩家取回; 判定按&quot;所属页是否声明该槽位&quot;, 其他页的饰品不会被当成孤儿</li><li><strong>管理员可代看代编</strong>: <code>/eacc admin view</code> 是只读查看, <code>/eacc admin edit</code> 还需要额外的 <code>emakiaccessory.admin.edit</code> 权限</li><li><strong>只收显式声明的饰品</strong>: 物品要先在 EmakiItem 定义里用 <code>accessory_slot</code> 效果声明可放入的饰品槽. 声明会写入物品 PDC (插件自定义数据, 即物品身上由插件写入的隐藏字段) 的 <code>emakiitem:accessory_slots</code>. 未声明或声明不匹配的物品放不进去; 已在槽内但不再匹配的, 会在关闭界面时连物带提示退回背包</li><li><strong>条件与耐久检查</strong>: 饰品按自身 EmakiItem 定义的 <code>condition</code> 做检查, 条件不满足或耐久扣满时属性, 技能与套装件数全部停止生效, 物品保留在槽内并在界面标注状态. 耐久扣除由 <code>durability.enabled</code> 控制, 默认关闭</li></ul><h2 id="文件结构" tabindex="-1">文件结构 <a class="header-anchor" href="#文件结构" aria-label="Permalink to “文件结构”">​</a></h2><p>服务器运行后, EmakiAccessory 主要使用以下文件:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiAccessory/</span></span>
<span class="line"><span>├─ config.yml</span></span>
<span class="line"><span>├─ parts.yml</span></span>
<span class="line"><span>├─ pages/</span></span>
<span class="line"><span>│  ├─ main.yml</span></span>
<span class="line"><span>│  ├─ secondary.yml</span></span>
<span class="line"><span>│  ├─ example_battle.yml</span></span>
<span class="line"><span>│  └─ example_collection.yml</span></span>
<span class="line"><span>├─ sets/</span></span>
<span class="line"><span>│  ├─ example_set.yml</span></span>
<span class="line"><span>│  └─ example_ring_set.yml</span></span>
<span class="line"><span>├─ gui/</span></span>
<span class="line"><span>│  ├─ accessory_gui.yml</span></span>
<span class="line"><span>│  ├─ editor_browser_gui.yml</span></span>
<span class="line"><span>│  └─ editor_page_gui.yml</span></span>
<span class="line"><span>└─ lang/</span></span>
<span class="line"><span>   ├─ zh_CN.yml</span></span>
<span class="line"><span>   └─ en_US.yml</span></span></code></pre></div><table tabindex="0"><thead><tr><th>路径</th><th>说明</th></tr></thead><tbody><tr><td><code>config.yml</code></td><td>主配置: 槽位来源, 耐久度开关, 死亡掉落, 去重, 持久化</td></tr><tr><td><code>parts.yml</code></td><td>饰品部位定义, 决定全局有哪些槽位实例</td></tr><tr><td><code>pages/&lt;页&gt;.yml</code></td><td>饰品页定义. 页 id 取 <code>page_id</code>, 文件名不参与识别; <code>parts</code> 决定该页启用哪些部位</td></tr><tr><td><code>sets/&lt;套装&gt;.yml</code></td><td>饰品套装定义. 一个文件一个套装, 文件名不参与识别</td></tr><tr><td><code>gui/accessory_gui.yml</code></td><td>饰品栏界面模板, 可被多页共用</td></tr><tr><td><code>lang/*.yml</code></td><td>命令, 界面与控制台文案</td></tr></tbody></table><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to “快速开始”">​</a></h2><ol><li>把 <code>EmakiCoreLib-*.jar</code> 与 <code>EmakiAccessory-*.jar</code> 放入服务器 <code>plugins/</code></li><li>想让饰品提供属性和技能, 还要安装 EmakiAttribute, EmakiSkills, 并用 EmakiItem 定义饰品物品 -- 记得在定义的 <code>effects</code> 里用 <code>type: &quot;accessory_slot&quot;</code> 声明可放入的饰品槽, 否则物品放不进饰品栏</li><li>注意, 不要把 <code>emaki-accessory-api-*.jar</code> 放进 <code>plugins/</code>; API Jar (提供给开发者编译用的接口包) 只作为编译依赖, 不参与服务器运行</li><li>首次启动后检查 <code>plugins/EmakiAccessory/parts.yml</code>, <code>pages/main.yml</code> 与 <code>gui/accessory_gui.yml</code></li><li>打开自己的饰品栏:</li></ol><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/eacc open</span></span>
<span class="line"><span>/eacc open secondary</span></span></code></pre></div><ol start="6"><li>查看所有页与当前启用页:</li></ol><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/eacc pages</span></span></code></pre></div><ol start="7"><li>修改配置后重载配置, 部位, 页与套装:</li></ol><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/eacc reload</span></span></code></pre></div><h2 id="使用提示" tabindex="-1">使用提示 <a class="header-anchor" href="#使用提示" aria-label="Permalink to “使用提示”">​</a></h2><ul><li>你改了 <code>parts.yml</code> 的部位或 <code>count</code> 之后, 要在 <code>gui/accessory_gui.yml</code> 里为每个展开出的槽位实例摆一格 <code>type: &quot;accessory_slot&quot;</code> 且键名相同的格子, 否则玩家用不到该槽位. 还要确认目标页的 <code>parts</code> 里声明了该部位</li><li>属性, 技能与套装件数只统计当前启用页. 玩家换页前, 新页的饰品不会生效</li><li><code>unique: true</code> (只允许放一件同类饰品) 优先按 EmakiItem 的物品定义 id 判定, 且只在<strong>同一页内</strong>比较. 缺少 EmakiItem 时它不会失效, 而是回退为原版材质判定, 此时同材质的两件饰品会被视为重复</li><li>饰品套装的 <code>pieces[].item</code> 同样依赖 EmakiItem 的定义 id, 缺少 EmakiItem 时整个套装不生效</li><li>部位 id 不能以 <code>_&lt;数字&gt;</code> 结尾, 那会与槽位实例 id 撞车</li><li><code>/eacc retrieve &lt;页&gt;</code> 取回的是<strong>该页全部</strong>饰品 (已声明槽位与孤儿槽一起取出), 页打不开时可以用它备用取回</li><li><code>/eacc admin edit</code> 只对在线玩家有效; <code>/eacc admin clear</code> 不可撤销且会记入日志, 执行前先确认</li><li>EmakiSkills 是软依赖: 没装它时饰品与套装的技能不生效, 但模块照常启用 (技能集成按类名查找并加载)</li></ul>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};